from __future__ import annotations

from pydantic import Field
from typing_extensions import TypedDict

from ..core import SdkBaseModel


class ConfirmPaymentRequest(SdkBaseModel):
    balance_account_id: str = Field(alias="balanceAccountId")
    """The balance account ID of the account where the funds should be subtracted."""

    token: str
    """The payment token is an identifier for the payment. It is generated by Adyen on the response of the payment
    details."""


class ConfirmPaymentRequestDict(TypedDict):
    balance_account_id: str
    token: str
